package com.kwl360.stickermaker;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import org.json.*;
public class MainActivity extends Activity {
 LinearLayout root;String selected;static final int PICK=55, PICK_ZIP=56;
 @Override public void onCreate(Bundle b){super.onCreate(b);render();}
 TextView label(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(Color.rgb(15,23,42));v.setPadding(6,14,6,14);return v;}
 Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());return b;}
 void render(){ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(22,25,22,25);root.setBackgroundColor(Color.rgb(248,250,252));scroll.addView(root);setContentView(scroll);
 root.addView(label("🇵🇸 صانع ملصقات KWL",26));root.addView(label("أنشئ حزمًا متعددة، وارفع صورًا جديدة في أي وقت دون إعادة تثبيت التطبيق. كل حزمة تضم 3–30 ملصقًا.",16));
 root.addView(button("📦 استيراد حزمة ZIP",()->{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("application/zip");intent.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,PICK_ZIP);}));
 root.addView(button("➕ إنشاء حزمة جديدة",()->{EditText t=new EditText(this);t.setHint("مثال: ملصقات الحب");new AlertDialog.Builder(this).setTitle("اسم الحزمة").setView(t).setPositiveButton("إنشاء",(d,w)->{try{String input=t.getText().toString().trim();final String name=input.isEmpty()?"ملصقاتي":input;new AlertDialog.Builder(this).setTitle("نوع الحزمة").setItems(new String[]{"ثابتة (PNG / JPG / WebP)","متحركة (WebP متحرك 512×512)"},(dialog,which)->{try{selected=PackStore.create(this,name,which==1);render();}catch(Exception ex){error(ex.getMessage());}}).show();}catch(Exception e){error(e.getMessage());}}).setNegativeButton("إلغاء",null).show();}));
 JSONArray a=PackStore.packs(this);for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p==null)continue;String id=p.optString("id");int n=PackStore.count(this,id);root.addView(label("📦 "+p.optString("name")+(p.optBoolean("animated")?" 🎞️ متحركة":" 🖼️ ثابتة")+" — "+n+"/30 ملصق",20));root.addView(button("📷 إضافة صور لهذه الحزمة",()->{selected=id;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType(PackStore.get(this,id).optBoolean("animated")?"image/webp":"image/*");intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);intent.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,PICK);}));root.addView(button("✅ إضافة الحزمة إلى واتساب",()->install(id,"com.whatsapp")));root.addView(button("واتساب الأعمال",()->install(id,"com.whatsapp.w4b")));root.addView(button("✏️ تغيير اسم الحزمة",()->{EditText t=new EditText(this);t.setText(PackStore.get(this,id).optString("name"));new AlertDialog.Builder(this).setTitle("تغيير اسم الحزمة").setView(t).setPositiveButton("حفظ",(d,w)->{try{String name=t.getText().toString().trim();if(name.isEmpty())throw new Exception("اسم الحزمة مطلوب");PackStore.rename(this,id,name);render();}catch(Exception e){error(e.getMessage());}}).setNegativeButton("إلغاء",null).show();}));
 root.addView(button("🖼️ عرض وإدارة الملصقات",()->showStickers(id)));
 root.addView(button("🗑 حذف الحزمة",()->new AlertDialog.Builder(this).setMessage("حذف الحزمة وصورها؟").setPositiveButton("حذف",(d,w)->{PackStore.delete(this,id);render();}).setNegativeButton("إلغاء",null).show()));}
 root.addView(label("ارفع صورك الجاهزة من الهاتف، واجمعها في حزم، ثم أضفها إلى واتساب.",14));}
 void install(String id,String pkg){int n=PackStore.count(this,id);if(n<3){error("أضف 3 ملصقات على الأقل قبل التثبيت");return;}Intent intent=new Intent("com.whatsapp.intent.action.ENABLE_STICKER_PACK");intent.putExtra("sticker_pack_id",id);intent.putExtra("sticker_pack_authority",PackStore.AUTH);intent.putExtra("sticker_pack_name",PackStore.get(this,id).optString("name"));intent.setPackage(pkg);try{startActivityForResult(intent,200);}catch(Exception e){error("تعذر فتح واتساب. تحقق من تثبيته.");}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK_ZIP&&result==RESULT_OK&&data!=null){UriImport(data);return;}if(request==PICK&&result==RESULT_OK&&data!=null){int ok=0;String err="";try{if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++){try{PackStore.add(this,selected,data.getClipData().getItemAt(i).getUri());ok++;}catch(Exception e){err=e.getMessage();break;}}}else if(data.getData()!=null){PackStore.add(this,selected,data.getData());ok++;}}catch(Exception e){err=e.getMessage();}render();Toast.makeText(this,"تمت إضافة "+ok+" ملصقات"+(err.isEmpty()?"":" — "+err),Toast.LENGTH_LONG).show();}}
 void showStickers(String id){JSONObject p=PackStore.get(this,id);if(p==null)return;JSONArray files=p.optJSONArray("files");if(files==null||files.length()==0){error("لا توجد ملصقات بعد");return;}String[] options=new String[files.length()];for(int i=0;i<files.length();i++)options[i]="ملصق "+(i+1);new AlertDialog.Builder(this).setTitle("اختر ملصقًا للمعاينة أو الحذف").setItems(options,(d,index)->preview(id,index)).setNegativeButton("إغلاق",null).show();}
 void preview(String id,int index){try{JSONObject p=PackStore.get(this,id);String filename=p.getJSONArray("files").getString(index);java.io.File file=new java.io.File(PackStore.dir(this,id),filename);android.graphics.ImageDecoder.Source src=android.graphics.ImageDecoder.createSource(file);android.graphics.drawable.Drawable drawable=android.graphics.ImageDecoder.decodeDrawable(src);ImageView image=new ImageView(this);image.setImageDrawable(drawable);image.setAdjustViewBounds(true);image.setMinimumHeight(260);new AlertDialog.Builder(this).setTitle("معاينة الملصق "+(index+1)).setView(image).setPositiveButton("حذف الملصق",(d,w)->{try{PackStore.removeSticker(this,id,index);render();}catch(Exception e){error(e.getMessage());}}).setNegativeButton("رجوع",null).show();}catch(Exception e){error(e.getMessage());}}
 void UriImport(Intent data){final android.net.Uri uri=data.getData();if(uri==null)return;new Thread(()->{try{ZipImporter.Result r=ZipImporter.run(this,uri);runOnUiThread(()->{render();new AlertDialog.Builder(this).setMessage("تم استيراد "+r.imported+" ملصق في "+r.packs+" حزمة. تم تجاوز "+r.skipped+" ملف. "+r.warning).setPositiveButton("حسنًا",null).show();});}catch(Exception e){runOnUiThread(()->error(e.getMessage()));}}).start();}
 void error(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("حسنًا",null).show();}
}